import{_ as a,o as l,c as r,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"2016Q3 Ceph社区季度进展报告","description":"","frontmatter":{"title":"2016Q3 Ceph社区季度进展报告","date":"2016-09-01T00:00:00.000Z","updated":"2016-09-01T00:00:00.000Z","categories":["季度总结"],"tags":["Ceph","社区动态","季度报告"],"subtitle":"2016Q3_quarterly_summary","outline":"deep"},"headers":[],"relativePath":"quarterly/2016Q3_Ceph社区季度总结.md","filePath":"quarterly/2016Q3_Ceph社区季度总结.md","lastUpdated":null}'),h={name:"quarterly/2016Q3_Ceph社区季度总结.md"};function i(t,e,n,s,_,p){return l(),r("div",null,[...e[0]||(e[0]=[o('<p>2016Q3 Ceph 社区季度进展报告已生成完毕。以下是完整内容：</p><hr><h1 id="_2016q3-ceph-社区季度进展报告" tabindex="-1">2016Q3 Ceph 社区季度进展报告 <a class="header-anchor" href="#_2016q3-ceph-社区季度进展报告" aria-label="Permalink to &quot;2016Q3 Ceph 社区季度进展报告&quot;">​</a></h1><p>2016年第三季度（7-9月），Ceph 社区围绕存储引擎优化、镜像管理增强、构建流程改进和管理工具集成等方向持续推进。本季度共记录4次会议讨论，涵盖开发者月度会议和技术分享，以下是详细进展。</p><hr><h2 id="一、本季度重点议题" tabindex="-1">一、本季度重点议题 <a class="header-anchor" href="#一、本季度重点议题" aria-label="Permalink to &quot;一、本季度重点议题&quot;">​</a></h2><h3 id="_1-bluestore-存储引擎优化" tabindex="-1">1. BlueStore 存储引擎优化 <a class="header-anchor" href="#_1-bluestore-存储引擎优化" aria-label="Permalink to &quot;1. BlueStore 存储引擎优化&quot;">​</a></h3><p>BlueStore 作为下一代存储后端，本季度在序列化和编解码框架上取得重要进展。开发者着重优化 onode 序列化过程，通过减少缓冲区操作层级、引入标志位指示常见优化场景（如无空洞、数据集中扩展等），显著降低 CPU 开销和存储空间需求。详见 <a href="/VideoSummary/posts/2016/2016-AUG-03_-_-_Ceph_Developer_Monthly.html">2016-AUG-03 - Ceph Developer Monthly</a>)。</p><h3 id="_2-rbd-镜像与缓存增强" tabindex="-1">2. RBD 镜像与缓存增强 <a class="header-anchor" href="#_2-rbd-镜像与缓存增强" aria-label="Permalink to &quot;2. RBD 镜像与缓存增强&quot;">​</a></h3><p>RBD 模块本季度讨论最为密集，涵盖镜像横向扩展、客户端持久缓存、快照一致性组三大方向。镜像横向扩展方案分三阶段推进：活动/被动故障转移、每镜像横向扩展、热点能力扩展；客户端持久缓存设计支持将读写负载卸载到本地，使用稀疏文件或 BlueStore 实例存储数据。详见 <a href="/VideoSummary/posts/2016/2016-AUG-03_-_-_Ceph_Developer_Monthly.html">2016-AUG-03 - Ceph Developer Monthly</a>) 和 <a href="/VideoSummary/posts/2016/2016-SEP-07_-_-_Ceph_Developer_Monthly.html">2016-SEP-07 - Ceph Developer Monthly</a>)。</p><h3 id="_3-构建与持续集成体系优化" tabindex="-1">3. 构建与持续集成体系优化 <a class="header-anchor" href="#_3-构建与持续集成体系优化" aria-label="Permalink to &quot;3. 构建与持续集成体系优化&quot;">​</a></h3><p>随着社区贡献者增长，原有 Jenkins 构建流程面临效率和可扩展性瓶颈。本季度讨论了基于 Docker 容器化和 Kubernetes 编排的弹性构建方案，以及使用 Nexus/Artifactory 进行依赖管理的改进计划。详见 <a href="/VideoSummary/posts/2016/2016-AUG-25_--_Ceph_Tech_Talk_-_Unified_CI.html">2016-AUG-25 - Ceph Tech Talk - Unified CI</a>)。</p><h3 id="_4-ceph-管理工具生态" tabindex="-1">4. Ceph 管理工具生态 <a class="header-anchor" href="#_4-ceph-管理工具生态" aria-label="Permalink to &quot;4. Ceph 管理工具生态&quot;">​</a></h3><p>OpenATTIC 开源存储管理平台与 Ceph 的集成工作持续推进，提供基于 librados 和 librbd API 的集群管理、健康监控（Nagios/RRDtool）和自动化（Saltstack）能力。详见 <a href="/VideoSummary/posts/2016/2016-JUN-23_--_Ceph_Tech_Talks_-_OpenATTIC.html">2016-JUN-23 - Ceph Tech Talks - OpenATTIC</a>)。</p><hr><h2 id="二、技术亮点" tabindex="-1">二、技术亮点 <a class="header-anchor" href="#二、技术亮点" aria-label="Permalink to &quot;二、技术亮点&quot;">​</a></h2><h3 id="bluestore-编解码框架重构" tabindex="-1">BlueStore 编解码框架重构 <a class="header-anchor" href="#bluestore-编解码框架重构" aria-label="Permalink to &quot;BlueStore 编解码框架重构&quot;">​</a></h3><ul><li>引入新的编码/解码框架，优化缓冲区操作和迭代器，减少代码层级和冗余</li><li>通过标志位指示常见优化场景（无空洞、数据集中扩展等）</li><li>对物理扩展引用进行优化，减少序列化冗余，降低存储空间需求</li></ul><h3 id="rbd-镜像横向扩展方案" tabindex="-1">RBD 镜像横向扩展方案 <a class="header-anchor" href="#rbd-镜像横向扩展方案" aria-label="Permalink to &quot;RBD 镜像横向扩展方案&quot;">​</a></h3><ul><li><strong>第一阶段</strong>：活动/被动故障转移，通过锁机制实现高可用性</li><li><strong>第二阶段</strong>：每镜像横向扩展，通过 RPC 消息分配负载</li><li><strong>第三阶段</strong>：热点能力扩展，通过收集指标平衡负载</li></ul><h3 id="rbd-客户端持久缓存" tabindex="-1">RBD 客户端持久缓存 <a class="header-anchor" href="#rbd-客户端持久缓存" aria-label="Permalink to &quot;RBD 客户端持久缓存&quot;">​</a></h3><ul><li>支持读取和写入数据缓存，支持克隆图像的共享读取缓存</li><li>缓存使用稀疏文件或 BlueStore 实例存储</li><li>缓存管理器负责分配缓存槽位和垃圾回收</li></ul><h3 id="rbd-快照与一致性组" tabindex="-1">RBD 快照与一致性组 <a class="header-anchor" href="#rbd-快照与一致性组" aria-label="Permalink to &quot;RBD 快照与一致性组&quot;">​</a></h3><ul><li>在快照设计中添加&quot;快照类型&quot;字段，区分用户快照和一致性组快照</li><li>支持并行创建快照，包含异常处理和失败恢复机制</li><li>详见 <a href="/VideoSummary/posts/2016/2016-SEP-07_-_-_Ceph_Developer_Monthly.html">2016-SEP-07 - Ceph Developer Monthly</a>)</li></ul><h3 id="mds-元数据负载均衡器-mantle" tabindex="-1">MDS 元数据负载均衡器（Mantle） <a class="header-anchor" href="#mds-元数据负载均衡器-mantle" aria-label="Permalink to &quot;MDS 元数据负载均衡器（Mantle）&quot;">​</a></h3><ul><li>Mantle 通过 Lua 脚本注入控制负载均衡策略，实现策略与机制分离</li><li>使用 Lua 作为脚本语言，可灵活更改负载均衡策略</li><li>当前处于实验阶段，不建议生产环境使用</li><li>详见 <a href="/VideoSummary/posts/2016/2016-AUG-03_-_-_Ceph_Developer_Monthly.html">2016-AUG-03 - Ceph Developer Monthly</a>)</li></ul><h3 id="simd-指令集检测-ec-库" tabindex="-1">SIMD 指令集检测（EC 库） <a class="header-anchor" href="#simd-指令集检测-ec-库" aria-label="Permalink to &quot;SIMD 指令集检测（EC 库）&quot;">​</a></h3><ul><li>在 EC 库中实现 SIMD 指令集检测，支持不同处理器的优化</li><li>处理不同指令集之间的兼容性问题</li><li>详见 <a href="/VideoSummary/posts/2016/2016-SEP-07_-_-_Ceph_Developer_Monthly.html">2016-SEP-07 - Ceph Developer Monthly</a>)</li></ul><h3 id="改进的-scrub-接口" tabindex="-1">改进的 Scrub 接口 <a class="header-anchor" href="#改进的-scrub-接口" aria-label="Permalink to &quot;改进的 Scrub 接口&quot;">​</a></h3><ul><li>通过比较每个分片的对象信息，更准确识别损坏对象</li><li>提供 JSON 输出，便于用户和脚本识别修复损坏对象</li><li>详见 <a href="/VideoSummary/posts/2016/2016-AUG-03_-_-_Ceph_Developer_Monthly.html">2016-AUG-03 - Ceph Developer Monthly</a>)</li></ul><hr><h2 id="三、重要决策与里程碑" tabindex="-1">三、重要决策与里程碑 <a class="header-anchor" href="#三、重要决策与里程碑" aria-label="Permalink to &quot;三、重要决策与里程碑&quot;">​</a></h2><h3 id="manager-组件引入" tabindex="-1">Manager 组件引入 <a class="header-anchor" href="#manager-组件引入" aria-label="Permalink to &quot;Manager 组件引入&quot;">​</a></h3><ul><li>Manager 作为可选组件，用于存储 PG 状态和统计信息</li><li>PG 状态将在 Luminous 版本中从 Monitor 移动到 Manager</li><li>Kraken 版本中将提供实验性的 Manager 支持</li><li>详见 <a href="/VideoSummary/posts/2016/2016-AUG-03_-_-_Ceph_Developer_Monthly.html">2016-AUG-03 - Ceph Developer Monthly</a>)</li></ul><h3 id="ec-覆写功能推进" tabindex="-1">EC 覆写功能推进 <a class="header-anchor" href="#ec-覆写功能推进" aria-label="Permalink to &quot;EC 覆写功能推进&quot;">​</a></h3><ul><li>工作包括持久化缺失集合、缓存和哈希基础设施更改</li><li>代码重构进行中，提高可维护性和可读性</li><li>详见 <a href="/VideoSummary/posts/2016/2016-AUG-03_-_-_Ceph_Developer_Monthly.html">2016-AUG-03 - Ceph Developer Monthly</a>)</li></ul><h3 id="ddo-数据去重-进展" tabindex="-1">DDO（数据去重）进展 <a class="header-anchor" href="#ddo-数据去重-进展" aria-label="Permalink to &quot;DDO（数据去重）进展&quot;">​</a></h3><ul><li>已完成 Python 原型，计划重写为 C++</li><li>DDO 用于存储内容地址对象，具有数据去重功能</li><li>详见 <a href="/VideoSummary/posts/2016/2016-AUG-03_-_-_Ceph_Developer_Monthly.html">2016-AUG-03 - Ceph Developer Monthly</a>)</li></ul><h3 id="kerberos-认证方案讨论" tabindex="-1">Kerberos 认证方案讨论 <a class="header-anchor" href="#kerberos-认证方案讨论" aria-label="Permalink to &quot;Kerberos 认证方案讨论&quot;">​</a></h3><ul><li>定义新的认证类型 &quot;Kerberos 5&quot;，直接与 libkrb5 库交互</li><li>在 Monitor 中实现认证逻辑，将用户身份映射到 Ceph 用户数据库</li><li>考虑使用&quot;混合令牌&quot;机制，将用户身份与 Ceph 身份结合</li><li>详见 <a href="/VideoSummary/posts/2016/2016-SEP-07_-_-_Ceph_Developer_Monthly.html">2016-SEP-07 - Ceph Developer Monthly</a>)</li></ul><h3 id="构建系统现代化" tabindex="-1">构建系统现代化 <a class="header-anchor" href="#构建系统现代化" aria-label="Permalink to &quot;构建系统现代化&quot;">​</a></h3><ul><li>从传统 Jenkins 迁移到基于 Docker + Kubernetes 的弹性构建体系</li><li>引入 Nexus/Artifactory 进行依赖管理，提高透明度</li><li>使用 Ansible 进行构建资源管理</li><li>详见 <a href="/VideoSummary/posts/2016/2016-AUG-25_--_Ceph_Tech_Talk_-_Unified_CI.html">2016-AUG-25 - Ceph Tech Talk - Unified CI</a>)</li></ul><hr><h2 id="四、社区动态" tabindex="-1">四、社区动态 <a class="header-anchor" href="#四、社区动态" aria-label="Permalink to &quot;四、社区动态&quot;">​</a></h2><h3 id="开发者月度会议" tabindex="-1">开发者月度会议 <a class="header-anchor" href="#开发者月度会议" aria-label="Permalink to &quot;开发者月度会议&quot;">​</a></h3><p>本季度举办了2次 Ceph Developer Monthly 会议（8月3日、9月7日），讨论了从存储引擎优化到认证机制的广泛议题。主要参与者包括 Sage、Jason、Sam、Dan、Basam、Alfredo 等核心开发者。</p><h3 id="技术分享" tabindex="-1">技术分享 <a class="header-anchor" href="#技术分享" aria-label="Permalink to &quot;技术分享&quot;">​</a></h3><ul><li><strong>统一 CI 构建优化</strong>（8月25日）：Alfredo Lisa 分享了 Ceph 构建和发布流程的优化方案，解决构建效率、可扩展性和依赖管理问题</li><li><strong>OpenATTIC 集成</strong>（6月23日）：Lens Scrimer 介绍了 OpenATTIC 与 Ceph 的集成工作，计划与 SUSE 开发者进行 Hack Week 协作开发</li></ul><h3 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h3><ul><li>社区成员继续讨论和反馈 Mantle 和 DDO 设计</li><li>推进 RBD 镜像横向扩展和 RBD 客户端持久缓存工作</li><li>完成 Manager 和 PG 状态迁移</li><li>准备 Kraken 和 Luminous 版本发布</li><li>详见 <a href="/VideoSummary/posts/2016/2016-AUG-03_-_-_Ceph_Developer_Monthly.html">2016-AUG-03 - Ceph Developer Monthly</a>)</li></ul><hr><h2 id="五、下季度展望" tabindex="-1">五、下季度展望 <a class="header-anchor" href="#五、下季度展望" aria-label="Permalink to &quot;五、下季度展望&quot;">​</a></h2><p>基于本季度讨论，预计下一季度将重点关注：</p><ol><li><strong>Kraken 版本发布准备</strong>：Manager 实验性支持、EC 覆写、DDO 等特性将进入功能完善阶段</li><li><strong>Luminous 版本规划</strong>：PG 状态从 Monitor 迁移到 Manager 的架构变更将开始落地</li><li><strong>RBD 特性完善</strong>：镜像横向扩展、客户端持久缓存、快照一致性组等特性将推进到可测试状态</li><li><strong>BlueStore 稳定性</strong>：编解码框架优化完成后，将进入更广泛的测试和验证阶段</li><li><strong>构建体系全面切换</strong>：Docker + Kubernetes 构建方案将逐步替代传统 Jenkins 流程</li><li><strong>管理工具生态</strong>：OpenATTIC 的 Ceph 管理功能将持续完善，Dashboard 功能逐步增强</li></ol><hr><h2 id="参考文章" tabindex="-1">参考文章 <a class="header-anchor" href="#参考文章" aria-label="Permalink to &quot;参考文章&quot;">​</a></h2><ul><li><a href="/VideoSummary/posts/2016/2016-AUG-03_-_-_Ceph_Developer_Monthly.html">2016-AUG-03 - Ceph Developer Monthly</a>)</li><li><a href="/VideoSummary/posts/2016/2016-AUG-25_--_Ceph_Tech_Talk_-_Unified_CI.html">2016-AUG-25 - Ceph Tech Talk - Unified CI</a>)</li><li><a href="/VideoSummary/posts/2016/2016-JUN-23_--_Ceph_Tech_Talks_-_OpenATTIC.html">2016-JUN-23 - Ceph Tech Talks - OpenATTIC</a>)</li><li><a href="/VideoSummary/posts/2016/2016-SEP-07_-_-_Ceph_Developer_Monthly.html">2016-SEP-07 - Ceph Developer Monthly</a>)</li></ul><hr><p>报告已生成。如需写入文件，请授予 <code>temp_posts/2016Q3_Ceph社区季度总结.md</code> 的写入权限。</p><hr><h2 id="参考文章-1" tabindex="-1">参考文章 <a class="header-anchor" href="#参考文章-1" aria-label="Permalink to &quot;参考文章&quot;">​</a></h2><ul><li><a href="/VideoSummary/posts/2016/2016-AUG-03_-_-_Ceph_Developer_Monthly.html">2016-AUG-03 :: Ceph Developer Monthly</a>)</li><li><a href="/VideoSummary/posts/2016/2016-AUG-25_--_Ceph_Tech_Talk_-_Unified_CI.html">2016-AUG-25 -- Ceph Tech Talk: Unified CI</a>)</li><li><a href="/VideoSummary/posts/2016/2016-JUN-23_--_Ceph_Tech_Talks_-_OpenATTIC.html">2016-JUN-23 -- Ceph Tech Talks: OpenATTIC</a>)</li><li><a href="/VideoSummary/posts/2016/2016-SEP-07_-_-_Ceph_Developer_Monthly.html">2016-SEP-07 :: Ceph Developer Monthly</a>)</li></ul>',62)])])}const m=a(h,[["render",i]]);export{d as __pageData,m as default};
